-- Technical + Building Specs seed — 9 categories
-- Generated: 2026-09-06T03:34:12.800Z
-- Run in phpMyAdmin > SQL tab against: abongsha_bongshai_app
-- =============================================================

-- Step 1: Remove ALL existing specs for these 9 categories
DELETE FROM `category_specs` WHERE `category_id` IN (37, 41, 44, 40, 39, 45, 46, 47, 51);

-- Step 2: Insert fresh Technical + Building specs

-- Step 3: Verify row counts per category + spec_type
SELECT c.id, c.name, cs.spec_type, COUNT(*) AS row_count
FROM `categories` c
LEFT JOIN `category_specs` cs ON cs.category_id = c.id
WHERE c.id IN (37, 41, 44, 40, 39, 45, 46, 47, 51)
GROUP BY c.id, c.name, cs.spec_type
ORDER BY c.id, cs.spec_type;